package live.hogar.receiver.fairplay

import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Vectores generados compilando la implementacion C de UxPlay (playfair) con entradas aleatorias:
 * (mensaje3 de 164 bytes, ekey de 72 bytes, clave AES esperada). Comprueba el port de punta a punta.
 */
class PlayFairTest {
    private val vectors = listOf(
        Triple(
            "",
            "90d19838b0d7ec0b3e97818ecb96c4dbadbe172296d5234a42b24c6ba4e6ed24ec636a8ac0a1271e5866279238aaf84e58056d8f2fa8edd094ba97ae8b15442ee2db611a91bfe394",
            "7ea924cca5ba926945c937c5d5ab1bce",
        ),
        Triple(
            "",
            "38bdecface4abd12108f391ebc070e83e8180a6bd4f43a2afffcd3c12ef890575575e826e2cbeaee82af2c7d696cf46b977c090af4e146f6d03110ab86efde139eeabac37a0dde8e",
            "29e665c5ceba48b014588590c8ab888e",
        ),
        Triple(
            "",
            "29b2ff5ae637052b3839659c78fdf91d0aaa627e00a3170ffb76dc37c1eaaac499239549cf701c21e66105bd83af633f509fdc659c471564d277b4eab08215df3c101b7fe7f9a014",
            "a3abc8cfa0677c14b2075ec3ded532e5",
        ),
        Triple(
            "",
            "11bdfb90f5889051c039fef3263620202d31c4b0b2a8f4db163ff7837ae041f3f48e1a9ec2e1aba7db721bad818862bd657ad20d5d9ae6748fcb47e63483f8de9114acc7b6d0aef3",
            "647fa3f7c482efc4ca9dcbc4d82120a7",
        ),
        Triple(
            "",
            "7c8d99f47185ee580ff82e9aa8d0395d92fd6179ab96721fc3ce871d26ee53d92407f27cdafa3bfea39b52fad7154b77682cfb7a8b96dc7bbe8dd54f9e89fc155ae2e424b3f7281a",
            "3ddf4dcf2e7ac7f1b4264b29ec8db310",
        ),
        Triple(
            "",
            "c2ec6454bddbeda2424219395286fc9c6033bfcfb188d4c90b1d24fc026b21c28ae145da0717f531922a5bcea582483d97447ed136409366675168bdfdc6a6cd65990b3a31d32d33",
