            "4347c1e8b99129a70ed61058d973b5ccff5ea4a4eb0ab4154d8babd539241ca90901b21e8927e7e807147763700045c8716724b6923409c0a1980633915a607abe3996e37f99b32d",
            "d5d3941010f5ace2cfbf0455c3aca273",
        ),
        Triple(
            "",
            "c16ca5032ba9a2cc2b428cf85c63f3b9451451a6f9444f1af903ce8615fcdebf0b0902ef88efa52389220e6fb3808efc798b2adff4c4de3115e97ed30d5cb8dffcde0636d2982a07",
            "0e353b04767ed37d88d793a488f23718",
        ),
    )

    private fun hex(s: String) = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
    private fun ByteArray.toHex() = joinToString("") { "%02x".format(it) }

    @Test
    fun descifraComoLaImplementacionC() {
        for ((i, v) in vectors.withIndex()) {
            val out = PlayFair.decrypt(hex(v.first), hex(v.second))
            assertEquals("vector $i", v.third, out.toHex())
        }
    }
}
